//! Decodes the Python-reference golden fixtures (`tests/fixtures/`) with the
//! Rust codec and compares every event against `golden.json`.
//!
//! The fixtures are generated by `tests/gen_golden.py` using the upstream
//! Python implementation (rhasspy/wyoming @ 08a0c25) and committed, so this
//! test needs no Python.

use std::fs;
use std::io::Cursor;
use std::path::PathBuf;

use serde::Deserialize;
use serde_json::Value;
use wyoming::events::EventKind;
use wyoming::{decode, Event};

#[derive(Deserialize)]
struct Expected {
    #[serde(rename = "type")]
    type_: String,
    data: Value,
    payload_hex: Option<String>,
}

fn fixtures_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

#[test]
fn golden_stream_decodes_to_expected_events() {
    let dir = fixtures_dir();
    let bytes = fs::read(dir.join("golden.wyoming")).expect("golden.wyoming exists");
    let expected: Vec<Expected> =
        serde_json::from_slice(&fs::read(dir.join("golden.json")).expect("golden.json exists"))
            .expect("golden.json parses");

    let mut cursor = Cursor::new(&bytes[..]);
    let mut decoded: Vec<Event> = Vec::new();
    while let Some(event) = decode(&mut cursor).expect("decode succeeds") {
        decoded.push(event);
    }

    assert_eq!(
        decoded.len(),
        expected.len(),
        "event count must match golden.json"
    );

    for (i, (event, want)) in decoded.iter().zip(expected.iter()).enumerate() {
        assert_eq!(event.type_, want.type_, "event {i} type");
        assert_eq!(
            Value::Object(event.data.clone()),
            want.data,
            "event {i} ({}) data",
            want.type_
        );
        let want_payload = want.payload_hex.as_deref().map(unhex);
        assert_eq!(event.payload, want_payload, "event {i} ({}) payload", want.type_);
    }
}

#[test]
fn golden_stream_all_types_dispatch_through_eventkind() {
    let dir = fixtures_dir();
    let bytes = fs::read(dir.join("golden.wyoming")).expect("golden.wyoming exists");
    let mut cursor = Cursor::new(&bytes[..]);
    let mut n = 0;
    while let Some(event) = decode(&mut cursor).expect("decode succeeds") {
        let kind = EventKind::from_event(&event)
            .unwrap_or_else(|err| panic!("event {n} ({}) must dispatch: {err}", event.type_));
        // Re-encoding through the typed path must yield the same logical event.
        assert_eq!(kind.to_event(), event, "event {n} ({}) typed round-trip", event.type_);
        n += 1;
    }
    assert!(n >= 50, "fixture should cover the whole protocol, got {n} events");
}
